// The app icon assets that electron-builder packages (generated by scripts/make-icons.py from
// build/icon-source.png): sizes, transparency outside the rounded square, Apple's icon grid, the
// .icns representations, and that the packaging config points at files that exist.
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { inflateSync } from "node:zlib";
import { describe, expect, it } from "vitest";

const root = join(__dirname, "..");
const build = join(root, "build");

/** Minimal decoder for the 8-bit RGBA, non-interlaced PNGs the icon script writes. */
function decodePng(file: string) {
  const buf = readFileSync(file);
  expect(buf.subarray(0, 8).toString("hex")).toBe("89504e470d0a1a0a");
  let off = 8;
  let width = 0, height = 0, bitDepth = 0, colorType = 0, interlace = 0;
  const idat: Buffer[] = [];
  while (off < buf.length) {
    const len = buf.readUInt32BE(off);
    const type = buf.toString("ascii", off + 4, off + 8);
    const data = buf.subarray(off + 8, off + 8 + len);
    if (type === "IHDR") {
      width = data.readUInt32BE(0);
      height = data.readUInt32BE(4);
      bitDepth = data[8]!;
      colorType = data[9]!;
      interlace = data[12]!;
    } else if (type === "IDAT") idat.push(data);
    off += 12 + len;
  }
  expect({ bitDepth, colorType, interlace }).toEqual({ bitDepth: 8, colorType: 6, interlace: 0 }); // RGBA
  const raw = inflateSync(Buffer.concat(idat));
  const stride = width * 4;
  const px = Buffer.alloc(height * stride);
  for (let y = 0; y < height; y++) {
    const filter = raw[y * (stride + 1)]!;
    const line = raw.subarray(y * (stride + 1) + 1, (y + 1) * (stride + 1));
    for (let x = 0; x < stride; x++) {
      const a = x >= 4 ? px[y * stride + x - 4]! : 0;
      const b = y > 0 ? px[(y - 1) * stride + x]! : 0;
      const c = x >= 4 && y > 0 ? px[(y - 1) * stride + x - 4]! : 0;
      let v = line[x]!;
      if (filter === 1) v += a;
      else if (filter === 2) v += b;
      else if (filter === 3) v += (a + b) >> 1;
      else if (filter === 4) {
        const p = a + b - c, pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c);
        v += pa <= pb && pa <= pc ? a : pb <= pc ? b : c;
      }
      px[y * stride + x] = v & 0xff;
    }
  }
  return { width, height, alpha: (x: number, y: number) => px[(y * width + x) * 4 + 3]! };
}

/** Columns/rows where the icon is (almost) opaque: the body, not the shadow. */
function opaqueExtent(img: ReturnType<typeof decodePng>) {
  let min = img.width, max = -1;
  const mid = img.height >> 1;
  for (let x = 0; x < img.width; x++) if (img.alpha(x, mid) > 250) { min = Math.min(min, x); max = Math.max(max, x); }
  return { min, max, size: max - min + 1 };
}

describe("app icon assets", () => {
  it("macOS icon.png follows Apple's grid: transparent corners, 824 px opaque body on 1024", () => {
    const img = decodePng(join(build, "icon.png"));
    expect([img.width, img.height]).toEqual([1024, 1024]);
    for (const [x, y] of [[0, 0], [1023, 0], [0, 1023], [1023, 1023], [110, 110], [913, 110]]) expect(img.alpha(x!, y!), `corner ${x},${y}`).toBe(0);
    expect(img.alpha(512, 512)).toBe(255);
    const body = opaqueExtent(img);
    expect(body.size).toBeGreaterThanOrEqual(818);
    expect(body.size).toBeLessThanOrEqual(826);
    expect(Math.abs(body.min - (1023 - body.max))).toBeLessThanOrEqual(2); // centred
  });

  it("Linux icons exist in every size, square, with transparent corners and an opaque centre", () => {
    for (const size of [16, 32, 48, 64, 128, 256, 512, 1024]) {
      const img = decodePng(join(build, "icons", `${size}x${size}.png`));
      expect([img.width, img.height], `${size}`).toEqual([size, size]);
      // Linux icons keep only a small margin, so at 16 px the anti-aliased corner is nearly, not fully, clear.
      expect(img.alpha(0, 0), `${size} corner`).toBeLessThanOrEqual(8);
      expect(img.alpha(size >> 1, size >> 1), `${size} centre`).toBe(255);
    }
  });

  it("icon.icns holds every size from 16 px to 1024 px", () => {
    const buf = readFileSync(join(build, "icon.icns"));
    expect(buf.toString("ascii", 0, 4)).toBe("icns");
    expect(buf.readUInt32BE(4)).toBe(buf.length);
    const types = new Set<string>();
    const pngSizes = new Set<number>();
    for (let off = 8; off < buf.length; off += buf.readUInt32BE(off + 4)) {
      types.add(buf.toString("ascii", off, off + 4));
      const data = buf.subarray(off + 8, off + buf.readUInt32BE(off + 4));
      if (data.subarray(1, 4).toString("ascii") === "PNG") pngSizes.add(data.readUInt32BE(16));
    }
    // iconutil stores 16 and 32 px as raw ARGB (ic04, ic05) and the rest as PNG.
    for (const t of ["ic04", "ic05", "ic07", "ic08", "ic09", "ic10", "ic11", "ic12", "ic13", "ic14"]) expect(types, t).toContain(t);
    expect([...pngSizes].sort((a, b) => a - b)).toEqual([32, 64, 128, 256, 512, 1024]);
  });

  it("electron-builder points at icon files that exist", () => {
    const yml = readFileSync(join(root, "electron-builder.yml"), "utf8");
    const mac = /^mac:[\s\S]*?^\s+icon:\s*(\S+)/m.exec(yml)?.[1];
    const linux = /^linux:[\s\S]*?^\s+icon:\s*(\S+)/m.exec(yml)?.[1];
    expect(mac).toBe("build/icon.icns");
    expect(linux).toBe("build/icons");
    expect(existsSync(join(root, mac!))).toBe(true);
    expect(existsSync(join(root, linux!, "512x512.png"))).toBe(true);
    expect(existsSync(join(build, "icon-source.png"))).toBe(true);
  });
});
